recs = []
for i, r in enumerate(R, 1):
    (ntr, nen, date, war, place, lat, lon, loc, country, sa, sb, tc, oc, cat, res, st, src, disp, note, note_en) = r
    src = src + [s for s in EXTRA_SRC.get(i, []) + EXTRA_SRC.get(ntr, []) if s not in src]  # anahtar: sıra no ya da kayıt adı
    rec = {"id": i, "name_tr": ntr, "name_en": nen, "date": date, "hijri": "", "type": "land", "war": war, "place": place,
           "lat": lat, "lon": lon, "loc": loc, "country": country, "side_a": sa, "side_b": sb, "turkic_cmd": tc, "opp_cmd": oc,
           "category": cat, "result": res, "status": st, "sources": src,
           "verify": {"tdvia": True, "tdvia2": len([s for s in src if s.startswith("TDVIA:")]) >= 2, "wp": False, "rom": False, "academic": False},
           "state": A, "home_batch": "anadolu-selcuklu"}
    if disp: rec["dispute"] = disp
    if note: rec["note"], rec["note_en"] = note, note_en
    if cat == "turk_arasi": rec["opp_state"] = "Dânişmendliler"
    rec.update(FIX.get(i, {}))
    rec.update(FIX_N.get(ntr, {}))
    if ntr in ROM_MATCH:
        if "ROM" not in rec["sources"]: rec["sources"].append("ROM")
        if ntr in ROM_NOTE: rec["dispute"] = ((rec.get("dispute") or "") + ROM_NOTE[ntr]).strip()
    rec["verify"]["rom"] = "ROM" in rec["sources"]
    rec["verify"]["academic"] = any(x.startswith("AKD:") for x in rec["sources"])
    rec["verify"]["tdvia"] = any(x.startswith("TDVIA:") for x in rec["sources"])
    if not rec.get("dispute"): rec.pop("dispute", None)
    recs.append(rec)

